import pandas as pd
import numpy as np

TARGET_COLUMN = 'target'


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Train a simple decision tree using numpy."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c != TARGET_COLUMN]
    X_train = train[feature_cols].values
    y_train = train[TARGET_COLUMN].values
    X_test = test[feature_cols].values

    # Simple decision stump classifier - find best split
    def find_best_split(X, y):
        best_gain = 0
        best_feature = None
        best_threshold = None

        # Current entropy
        p = np.mean(y)
        if p == 0 or p == 1:
            return None, None, 0
        parent_entropy = -(p * np.log2(p) + (1-p) * np.log2(1-p))

        n_features = X.shape[1]
        for feature_idx in range(n_features):
            feature_values = X[:, feature_idx]
            thresholds = np.percentile(feature_values, [25, 50, 75])

            for threshold in thresholds:
                left_mask = feature_values <= threshold
                right_mask = ~left_mask

                if np.sum(left_mask) == 0 or np.sum(right_mask) == 0:
                    continue

                y_left = y[left_mask]
                y_right = y[right_mask]

                p_left = np.mean(y_left)
                p_right = np.mean(y_right)

                if p_left == 0 or p_left == 1:
                    entropy_left = 0
                else:
                    entropy_left = -(p_left * np.log2(p_left) + (1-p_left) * np.log2(1-p_left))

                if p_right == 0 or p_right == 1:
                    entropy_right = 0
                else:
                    entropy_right = -(p_right * np.log2(p_right) + (1-p_right) * np.log2(1-p_right))

                weighted_entropy = (len(y_left) * entropy_left + len(y_right) * entropy_right) / len(y)
                gain = parent_entropy - weighted_entropy

                if gain > best_gain:
                    best_gain = gain
                    best_feature = feature_idx
                    best_threshold = threshold

        return best_feature, best_threshold, best_gain

    # Build a simple tree with multiple levels
    def build_tree(X, y, depth=0, max_depth=5):
        # If pure node or max depth reached
        if len(y) == 0:
            return {'prediction': 0}

        if np.all(y == y[0]) or depth >= max_depth:
            return {'prediction': int(np.round(np.mean(y)))}

        feature, threshold, gain = find_best_split(X, y)

        if feature is None or gain < 0.001:
            return {'prediction': int(np.round(np.mean(y)))}

        left_mask = X[:, feature] <= threshold
        right_mask = ~left_mask

        left_subtree = build_tree(X[left_mask], y[left_mask], depth + 1, max_depth)
        right_subtree = build_tree(X[right_mask], y[right_mask], depth + 1, max_depth)

        return {
            'feature': feature,
            'threshold': threshold,
            'left': left_subtree,
            'right': right_subtree
        }

    def predict_sample(tree, x):
        if 'prediction' in tree:
            return tree['prediction']
        if x[tree['feature']] <= tree['threshold']:
            return predict_sample(tree['left'], x)
        else:
            return predict_sample(tree['right'], x)

    # Train tree
    tree = build_tree(X_train, y_train, max_depth=7)

    # Predict
    predictions = [predict_sample(tree, x) for x in X_test]

    pd.DataFrame({'prediction': predictions}).to_csv(output_csv, index=False)
